    public function roundedToMicros(): string
    {
        $negative = $this->isNegative();
        $amount = $negative ? substr($this->amount, 1) : $this->amount;

        if (self::isZeroAmount($amount)) {
            return '0.000000';
        }
        $padded = (string) (new Number($amount))->add('0', 7);
        [$intPart, $frac] = array_pad(explode('.', $padded, 2), 2, '');
        $frac = str_pad($frac, 7, '0');
        $carry = (int) $frac[6] >= 5 ? 1 : 0;

        // micros = intPart * 1e6 + first6(frac) + carry
        $micros = (int) $intPart * 1_000_000 + (int) substr($frac, 0, 6) + $carry;

        $micros = str_pad((string) $micros, 7, '0', STR_PAD_LEFT);
        $out = substr($micros, -7);
        $out = substr($out, 0, -6).'.'.substr($out, -6);
        $out = preg_replace('/^0+(?=\d)/', '', $out) ?? $out;

        return ($negative ? '-' : '').$out;
    }

